"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type * as React from "react";
import { useEffect, useId, useRef, useState } from "react";

import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { EmailField } from "./email-field";
import type { EmailSettings } from "./email-field";
import { EASE_OUT, MOTION, wait } from "./motion";
import {
  AvatarField,
  BioField,
  UsernameField,
  useUsernameStatus,
} from "./profile-fields";
import type { UsernameStatus } from "./profile-fields";
import { SaveBar } from "./save-bar";
import type { SaveState } from "./save-bar";
import { DEFAULT_SETTINGS_NAV, SettingsNav } from "./settings-nav";
import type { SettingsNavGroup, SettingsNavigateHandler } from "./settings-nav";
import { SignInMethods } from "./sign-in-methods";
import type { SignInSettings } from "./sign-in-methods";
import { RING } from "./surface";

/* ─────────────────────────────────────────────────────────
 * PROFILE SETTINGS
 *
 * A settings page: the nav on the left (a pill row on phones), then two
 * groups of rows with a label on the left and the control on the right.
 *
 *   Profile               photo, full name, username, bio. These go
 *                         through the save bar, which shows only while
 *                         something changed.
 *   Sign-in & security    email, sign-in methods. These apply on their
 *                         own: emails change once a link is confirmed.
 *
 * TYPE: 3 sizes, 2 weights, 4 roles. Nothing else.
 *   title   18px / 500, tight   group titles, avatar initials
 *   label   14px / 500          row labels, values, buttons
 *   body    14px / 400          descriptions, nav, inputs, save bar
 *   meta    12px / 400          group labels, hints, counter, dates
 *   Colour carries state, never size or weight. Inputs are 16px on
 *   phones (shadcn's default, so iOS doesn't zoom).
 *
 * LAYOUT: a 14rem label column, 2rem gap and 24rem controls, so the panel
 * (40rem) ends on the controls' right edge. Rows are grouped by space
 * alone (48px apart), no dividers. Each label
 * sits on the first line of its control. Below lg each row stacks.
 * ───────────────────────────────────────────────────────── */

/** The profile fields the save bar saves together. */
export interface ProfileValues {
  /** Photo URL, or `null` to show initials. */
  avatar: string | null;
  /** Full name, e.g. "Sam Davies". */
  name: string;
  /** Username without the prefix, e.g. "samdavies": 3–20 lowercase letters, numbers or _. */
  username: string;
  /** A line or two about the person. */
  bio: string;
}

export interface ProfileSettingsProps {
  /** The profile as it's saved now. Defaults to a demo profile (Sam Davies). */
  defaultValues?: ProfileValues;
  /**
   * Saves the changed profile. Resolve once it's stored; reject to keep the
   * changes and show "Changes not saved". Defaults to a 0.9s demo save.
   */
  onSave?: (values: ProfileValues) => Promise<void>;
  /**
   * Resolves `true` when a username is free. Called 450ms after typing
   * stops. Defaults to a demo where admin, acme, root, sam and support are
   * taken.
   */
  checkUsername?: (username: string) => Promise<boolean>;
  /**
   * Uploads a picked photo and resolves to its URL, which goes into the
   * profile on Save. Defaults to a local preview URL (nothing is uploaded).
   */
  uploadAvatar?: (file: File) => Promise<string>;
  /** The primary and secondary email, and what to call when they change. Defaults to a demo. */
  emails?: EmailSettings;
  /** Passkeys and sign-in providers, and what to call when they change. Defaults to a demo. */
  signIn?: SignInSettings;
  /** Your product's name, used in the descriptions ("across Acme"). Defaults to "Acme". */
  productName?: string;
  /** Shown before the username: your profile URL. Defaults to "acme.com/". */
  usernamePrefix?: string;
  /** Longest bio, in characters. Defaults to 160. */
  bioMaxLength?: number;
  /** Largest photo, in megabytes. Defaults to 2. */
  avatarMaxMb?: number;
  /** The settings nav, in groups. Defaults to Account and Workspace. */
  nav?: SettingsNavGroup[];
  /** Id of the current nav item. Defaults to "profile". */
  activeItem?: string;
  /**
   * Runs before a nav link is followed: route with your router here. While
   * there are unsaved changes the block stays and nudges the save bar.
   */
  onNavigate?: SettingsNavigateHandler;
  /** Extra classes for the root element. */
  className?: string;
}

/* ─────────────────────────────────────────────────────────
 * DEMO DEFAULTS (module level, so they're stable between renders)
 * ───────────────────────────────────────────────────────── */

const DEMO_PROFILE: ProfileValues = {
  avatar: "https://craftui-pro.vercel.app/images/testimonials/sam-davies.jpg",
  bio: "Product designer at Acme. Building calm software for busy teams.",
  name: "Sam Davies",
  username: "samdavies",
};

const DEMO_TAKEN = new Set(["acme", "admin", "root", "sam", "support"]);

const demoSave = async () => {
  await wait(900);
};

const demoCheckUsername = async (username: string) => {
  await wait(300);
  return !DEMO_TAKEN.has(username);
};

const DEMO_EMAILS: EmailSettings = {
  onRemoveSecondary: async () => {
    await wait(300);
  },
  onResendLink: async () => {
    await wait(450);
  },
  onSendLink: async () => {
    await wait(900);
  },
  primary: { address: "sam@acme.com", verified: true },
  secondary: { address: "sam.davies@gmail.com", verified: false },
};

const DEMO_ACCOUNTS: Record<string, string> = {
  apple: "sam.davies@icloud.com",
  gitlab: "samdavies",
  microsoft: "sam.davies@outlook.com",
};

const DEMO_SIGN_IN: SignInSettings = {
  onAddPasskey: async () => {
    await wait(900);
    return {
      added: new Date().toISOString().slice(0, 10),
      id: `passkey-${Date.now()}`,
      lastUsed: null,
      name: "This device",
    };
  },
  onConnect: async (id) => {
    await wait(900);
    return DEMO_ACCOUNTS[id] ?? "samdavies";
  },
  onDisconnect: async () => {
    await wait(300);
  },
  onRemovePasskey: async () => {
    await wait(300);
  },
  passkeys: [
    {
      added: "2026-09-02",
      id: "passkey-1",
      lastUsed: "2026-11-17",
      name: "MacBook Pro",
    },
  ],
  providers: [
    {
      account: "sam.davies@gmail.com",
      id: "google",
      lastUsed: "2026-11-13",
      name: "Google",
    },
    {
      account: "samdavies",
      id: "github",
      lastUsed: "2024-10-24",
      name: "GitHub",
    },
    { id: "apple", name: "Apple" },
    { id: "microsoft", name: "Microsoft" },
    { id: "gitlab", name: "GitLab" },
  ],
};

/* ─────────────────────────────────────────────────────────
 * FORM STATE
 * ───────────────────────────────────────────────────────── */

const KEYS: (keyof ProfileValues)[] = ["avatar", "name", "username", "bio"];

const USERNAME_PROBLEM: Partial<Record<UsernameStatus, string>> = {
  checking: "Checking username…",
  error: "Unable to check your username. Try again.",
  invalid: "Use 3–20 lowercase letters, numbers or _",
  taken: "Choose a different username",
};

const useProfileForm = ({
  checkUsername,
  initial,
  onSave,
}: {
  checkUsername: (username: string) => Promise<boolean>;
  initial: ProfileValues;
  onSave: (values: ProfileValues) => Promise<void>;
}) => {
  const [saved, setSaved] = useState(initial);
  const [draft, setDraft] = useState(initial);
  const [saveState, setSaveState] = useState<SaveState>("idle");
  const [saveFailed, setSaveFailed] = useState(false);
  // Bumped each time someone tries to leave with unsaved changes.
  const [nudges, setNudges] = useState(0);
  const usernameStatus = useUsernameStatus(
    draft.username,
    saved.username,
    checkUsername,
    450
  );

  const changed = (key: keyof ProfileValues) => draft[key] !== saved[key];
  const changedCount = KEYS.filter(changed).length;

  let problem: string | null = null;
  if (draft.name.trim() === "") {
    problem = "Add your name";
  } else if (changed("username")) {
    problem = USERNAME_PROBLEM[usernameStatus] ?? null;
  }
  if (!problem && saveFailed) {
    problem = "Changes not saved. Check your connection and try again.";
  }

  const set = <K extends keyof ProfileValues>(
    key: K,
    value: ProfileValues[K]
  ) => {
    setSaveFailed(false);
    setDraft((current) => ({ ...current, [key]: value }));
  };

  const save = async () => {
    const snapshot = draft;
    setSaveState("saving");
    setSaveFailed(false);
    try {
      await onSave(snapshot);
    } catch {
      setSaveFailed(true);
      setSaveState("idle");
      return;
    }
    setSaved(snapshot);
    setSaveState("saved");
    await wait(MOTION.savedHold);
    setSaveState("idle");
  };

  return {
    changed,
    changedCount,
    discard: () => {
      setSaveFailed(false);
      setDraft(saved);
    },
    draft,
    nudge: () => setNudges((count) => count + 1),
    nudges,
    problem,
    save,
    saveState,
    saved,
    set,
    usernameStatus,
  };
};

/* ─────────────────────────────────────────────────────────
 * ROW: label (+ description) on the left, control on the right.
 * ───────────────────────────────────────────────────────── */

// How far each label moves down to sit on its control's first line.
const OFFSET = {
  // The email's 12px "Primary · Verified" line: the control moves down
  // 2px instead (see controlOffset).
  email: "",
  // 36px control, 20px line: (36 - 20) / 2.
  field: "lg:pt-2",
  // The Upload photo row, centred beside the 64px photo.
  photo: "lg:pt-2.5",
  // Textarea: 1px border + 8px padding.
  textarea: "lg:pt-[0.5625rem]",
} as const;

// A changed row's label gets a small dot (150ms ease-out; it appears once
// per edit, not per keystroke).
const ChangedDot = ({ show }: { show: boolean }) => {
  const reduce = useReducedMotion();
  return (
    <AnimatePresence initial={false}>
      {show ? (
        <motion.span
          initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: MOTION.status, ease: EASE_OUT }}
          className="bg-primary size-1.5 shrink-0 rounded-full"
        >
          <span className="sr-only">(changed)</span>
        </motion.span>
      ) : null}
    </AnimatePresence>
  );
};

const Row = ({
  changed = false,
  children,
  description,
  htmlFor,
  label,
  offset,
}: {
  changed?: boolean;
  children: React.ReactNode;
  description: string;
  htmlFor?: string;
  label: string;
  offset: keyof typeof OFFSET;
}) => {
  const Label = htmlFor ? "label" : "p";
  return (
    <div className="grid gap-3 py-6 lg:grid-cols-[minmax(0,14rem)_minmax(0,24rem)] lg:gap-8">
      <div className={cn("flex flex-col gap-1", OFFSET[offset])}>
        <Label
          htmlFor={htmlFor}
          className="flex items-center gap-2 text-sm font-medium"
        >
          {label}
          <ChangedDot show={changed} />
        </Label>
        <p className="text-muted-foreground text-sm text-pretty">
          {description}
        </p>
      </div>
      <div className={cn("min-w-0", offset === "email" && "lg:pt-0.5")}>
        {children}
      </div>
    </div>
  );
};

const GroupHeader = ({
  description,
  title,
}: {
  description: string;
  title: string;
}) => (
  <header className="flex flex-col gap-1">
    <h2 className="text-lg font-medium tracking-tight">{title}</h2>
    <p className="text-muted-foreground text-sm">{description}</p>
  </header>
);

/* ─────────────────────────────────────────────────────────
 * THE BLOCK
 * ───────────────────────────────────────────────────────── */

export const ProfileSettings = ({
  activeItem = "profile",
  avatarMaxMb = 2,
  bioMaxLength = 160,
  checkUsername = demoCheckUsername,
  className,
  defaultValues = DEMO_PROFILE,
  emails = DEMO_EMAILS,
  nav = DEFAULT_SETTINGS_NAV,
  onNavigate,
  onSave = demoSave,
  productName = "Acme",
  signIn = DEMO_SIGN_IN,
  uploadAvatar,
  usernamePrefix = "acme.com/",
}: ProfileSettingsProps) => {
  const id = useId();
  const form = useProfileForm({
    checkUsername,
    initial: defaultValues,
    onSave,
  });

  // Local preview URLs made for the default upload, freed on unmount.
  const previewUrls = useRef<string[]>([]);
  useEffect(
    () => () => {
      for (const url of previewUrls.current) {
        URL.revokeObjectURL(url);
      }
    },
    []
  );

  const pickPhoto = async (file: File) => {
    if (uploadAvatar) {
      form.set("avatar", await uploadAvatar(file));
      return;
    }
    const url = URL.createObjectURL(file);
    previewUrls.current.push(url);
    form.set("avatar", url);
  };

  return (
    <div
      data-slot="profile-settings"
      className={cn(
        "flex flex-col gap-6 md:flex-row md:gap-10 lg:gap-14",
        className
      )}
    >
      <SettingsNav
        active={activeItem}
        groups={nav}
        onNavigate={(event, item) => {
          // Leaving with unsaved changes: stay, and nudge the save bar.
          if (form.changedCount > 0) {
            event.preventDefault();
            form.nudge();
            return;
          }
          onNavigate?.(event, item);
        }}
      />

      <div className="min-w-0 flex-1">
        <div className="max-w-[40rem]">
          <GroupHeader
            title="Profile"
            description={`How you appear to your team across ${productName}.`}
          />
          <Row
            label="Photo"
            description={`Shown next to your name across ${productName}.`}
            offset="photo"
            changed={form.changed("avatar")}
          >
            <AvatarField
              maxMb={avatarMaxMb}
              name={form.draft.name}
              src={form.draft.avatar}
              onPick={pickPhoto}
              onRemove={() => form.set("avatar", null)}
            />
          </Row>
          <Row
            label="Full name"
            description="Used in comments, mentions and invites."
            htmlFor={`${id}-name`}
            offset="field"
            changed={form.changed("name")}
          >
            <Input
              id={`${id}-name`}
              value={form.draft.name}
              onChange={(event) => form.set("name", event.target.value)}
              autoComplete="name"
              aria-invalid={form.draft.name.trim() === ""}
              // Override: a shadow ring instead of the border.
              className={RING}
            />
          </Row>
          <Row
            label="Username"
            description="Your profile link and @mention handle."
            htmlFor={`${id}-username`}
            offset="field"
            changed={form.changed("username")}
          >
            <UsernameField
              id={`${id}-username`}
              prefix={usernamePrefix}
              saved={form.saved.username}
              status={form.usernameStatus}
              value={form.draft.username}
              onChange={(value) => form.set("username", value)}
            />
          </Row>
          <Row
            label="Bio"
            description="A line or two about you, shown on your profile."
            htmlFor={`${id}-bio`}
            offset="textarea"
            changed={form.changed("bio")}
          >
            <BioField
              id={`${id}-bio`}
              max={bioMaxLength}
              value={form.draft.bio}
              onChange={(value) => form.set("bio", value)}
            />
          </Row>

          {/* Second group: how you get in. Nothing here goes through Save. */}
          <div className="mt-10">
            <GroupHeader
              title="Sign-in & security"
              description="How you get into your account. Changes here apply right away."
            />
          </div>
          <Row
            label="Email"
            description="Primary is for sign-in. Secondary is for recovery."
            offset="email"
          >
            <EmailField emails={emails} />
          </Row>
          <SignInMethods settings={signIn} />

          <SaveBar
            changedCount={form.changedCount}
            nudges={form.nudges}
            problem={form.problem}
            state={form.saveState}
            onDiscard={form.discard}
            onSave={form.save}
          />
        </div>
      </div>
    </div>
  );
};

export default ProfileSettings;

"use client";

import {
  CreditCardIcon,
  Key01Icon,
  Notification03Icon,
  SlidersHorizontalIcon,
  SquareLock02Icon,
  UserGroupIcon,
  UserIcon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import type * as React from "react";
import { useLayoutEffect, useRef } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/* ─────────────────────────────────────────────────────────
 * SETTINGS NAV
 * Desktop (md and up): a column of ghost buttons in labelled groups.
 * Phones: one row of pills that scrolls sideways, the active one
 * scrolled into view. The active item changes colour and background,
 * never weight (a weight change shifts the text's width).
 * ───────────────────────────────────────────────────────── */

/** One link in the settings nav. */
export interface SettingsNavItem {
  /** Unique id; matched against `activeItem` to mark the current page. */
  id: string;
  /** Text shown in the nav, e.g. "Security". */
  label: string;
  /** A Hugeicons icon from `@hugeicons/core-free-icons`, e.g. `UserIcon`. */
  icon: typeof UserIcon;
  /** Where the link goes, e.g. "/settings/security". */
  href: string;
}

/** A labelled group of nav links, e.g. "Account". */
export interface SettingsNavGroup {
  /** Small heading above the group, e.g. "Workspace". Leave out for none. */
  label?: string;
  /** The links in the group, in order. */
  items: SettingsNavItem[];
}

/**
 * Runs before a nav link is followed. Call `event.preventDefault()` to stay
 * on the page, or route with your own router.
 */
export type SettingsNavigateHandler = (
  event: React.MouseEvent<HTMLAnchorElement>,
  item: SettingsNavItem
) => void;

export const DEFAULT_SETTINGS_NAV: SettingsNavGroup[] = [
  {
    items: [
      { href: "#profile", icon: UserIcon, id: "profile", label: "Profile" },
      {
        href: "#security",
        icon: SquareLock02Icon,
        id: "security",
        label: "Security",
      },
      {
        href: "#notifications",
        icon: Notification03Icon,
        id: "notifications",
        label: "Notifications",
      },
      {
        href: "#preferences",
        icon: SlidersHorizontalIcon,
        id: "preferences",
        label: "Preferences",
      },
    ],
    label: "Account",
  },
  {
    items: [
      {
        href: "#team",
        icon: UserGroupIcon,
        id: "team",
        label: "Team & members",
      },
      { href: "#api-keys", icon: Key01Icon, id: "api-keys", label: "API keys" },
      {
        href: "#billing",
        icon: CreditCardIcon,
        id: "billing",
        label: "Billing",
      },
    ],
    label: "Workspace",
  },
];

export const SettingsNav = ({
  active,
  groups,
  onNavigate,
}: {
  active: string;
  groups: SettingsNavGroup[];
  onNavigate?: SettingsNavigateHandler;
}) => {
  const rowRef = useRef<HTMLDivElement>(null);
  const items = groups.flatMap((group) => group.items);

  // Phones: bring the active pill into view without scrolling the page.
  useLayoutEffect(() => {
    const row = rowRef.current;
    const pill = row?.querySelector<HTMLElement>("[aria-current=page]");
    if (row && pill) {
      row.scrollLeft =
        pill.offsetLeft - (row.clientWidth - pill.offsetWidth) / 2;
    }
  }, [active]);

  return (
    <>
      <nav
        aria-label="Settings"
        className="hidden w-52 shrink-0 flex-col gap-6 md:flex lg:w-56"
      >
        {groups.map((group, index) => (
          <div key={group.label ?? index} className="flex flex-col gap-0.5">
            {group.label ? (
              <p className="text-muted-foreground px-2.5 pb-1.5 text-xs">
                {group.label}
              </p>
            ) : null}
            {group.items.map((item) => {
              const current = item.id === active;
              return (
                <Button
                  key={item.id}
                  asChild
                  variant="ghost"
                  size="sm"
                  // Overrides: left-aligned rows, the active one filled.
                  className={cn(
                    "h-8 justify-start gap-2.5 px-2.5 font-normal",
                    current
                      ? "bg-accent text-foreground"
                      : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  <a
                    href={item.href}
                    aria-current={current ? "page" : undefined}
                    onClick={(event) => onNavigate?.(event, item)}
                  >
                    <HugeiconsIcon
                      icon={item.icon}
                      strokeWidth={1.75}
                      className="size-4"
                    />
                    {item.label}
                  </a>
                </Button>
              );
            })}
          </div>
        ))}
      </nav>

      <nav aria-label="Settings" className="md:hidden">
        <div
          ref={rowRef}
          className="-mx-4 flex gap-1 overflow-x-auto px-4 pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
        >
          {items.map((item) => {
            const current = item.id === active;
            return (
              <Button
                key={item.id}
                asChild
                variant={current ? "secondary" : "ghost"}
                size="sm"
                className={cn(
                  "h-8 shrink-0 gap-2 rounded-full px-3 font-normal",
                  !current && "text-muted-foreground"
                )}
              >
                <a
                  href={item.href}
                  aria-current={current ? "page" : undefined}
                  onClick={(event) => onNavigate?.(event, item)}
                >
                  <HugeiconsIcon
                    icon={item.icon}
                    strokeWidth={1.75}
                    className="size-4"
                  />
                  {item.label}
                </a>
              </Button>
            );
          })}
        </div>
      </nav>
    </>
  );
};

"use client";

import {
  Alert02Icon,
  Camera01Icon,
  CheckmarkCircle02Icon,
  Loading03Icon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";

import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

import { EASE_OUT, MOTION, Reveal } from "./motion";
import { PHOTO_INSET, RING, RING_BUTTON } from "./surface";

const initialsOf = (name: string) =>
  name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("") || "?";

/* ─────────────────────────────────────────────────────────
 * PHOTO
 * Click the photo or drop an image on it. A new photo crossfades in
 * (0.96 → 1, 200ms ease-out); without one, the initials show. While an
 * image is dragged over it, it grows 4% and rings (150ms).
 * ───────────────────────────────────────────────────────── */

export const AvatarPhoto = ({
  className,
  name,
  src,
}: {
  className?: string;
  name: string;
  src: string | null;
}) => {
  const reduce = useReducedMotion();
  return (
    <Avatar className={cn("size-16", className)}>
      <AvatarFallback className="bg-muted text-muted-foreground text-lg font-medium">
        {initialsOf(name)}
      </AvatarFallback>
      <AnimatePresence initial={false}>
        {src ? (
          <motion.img
            key={src}
            src={src}
            alt=""
            className="absolute inset-0 size-full object-cover"
            initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.96 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: MOTION.swap, ease: EASE_OUT }}
          />
        ) : null}
      </AnimatePresence>
      {/* Inset ring + soft inner shadow: the photo's edge reads crisply. */}
      <span aria-hidden className={PHOTO_INSET} />
    </Avatar>
  );
};

const ACCEPTED = ["image/png", "image/jpeg", "image/webp"];

export const AvatarField = ({
  maxMb,
  name,
  onPick,
  onRemove,
  src,
}: {
  maxMb: number;
  name: string;
  onPick: (file: File) => void;
  onRemove: () => void;
  src: string | null;
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [dragging, setDragging] = useState(false);

  const take = (file: File | undefined) => {
    if (!file) {
      return;
    }
    if (!ACCEPTED.includes(file.type)) {
      setError("Choose a PNG, JPG or WebP image.");
      return;
    }
    if (file.size > maxMb * 1024 * 1024) {
      setError(`Choose an image under ${maxMb} MB.`);
      return;
    }
    setError(null);
    onPick(file);
  };

  return (
    <div className="flex items-center gap-4">
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        aria-label="Change photo"
        onDragOver={(event) => {
          event.preventDefault();
          setDragging(true);
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(event) => {
          event.preventDefault();
          setDragging(false);
          take(event.dataTransfer.files[0]);
        }}
        className={cn(
          "group/photo focus-visible:ring-ring/50 relative shrink-0 rounded-full outline-none focus-visible:ring-[3px]",
          // Children ignore the pointer, so dragging across them doesn't
          // flicker between dragover and dragleave.
          "transition-[scale,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none [&>*]:pointer-events-none",
          dragging &&
            "ring-primary ring-offset-background scale-[1.04] ring-2 ring-offset-2 motion-reduce:scale-100"
        )}
      >
        <AvatarPhoto name={name} src={src} />
        {/* Hover hint, only where there's a real hover. */}
        <span className="absolute inset-0 flex items-center justify-center rounded-full bg-black/45 text-white opacity-0 transition-opacity duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] group-hover/photo:opacity-100 group-focus-visible/photo:opacity-100 motion-reduce:transition-none">
          <HugeiconsIcon
            icon={Camera01Icon}
            strokeWidth={1.75}
            className="size-5"
          />
        </span>
      </button>
      <div className="flex flex-col gap-2">
        <div className="flex gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            className={RING_BUTTON}
            onClick={() => inputRef.current?.click()}
          >
            Upload photo
          </Button>
          {/* Comes and goes with the photo: a 150ms fade, no movement. */}
          <AnimatePresence initial={false}>
            {src ? (
              <motion.span
                key="remove"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: MOTION.status, ease: EASE_OUT }}
              >
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="text-muted-foreground"
                  onClick={onRemove}
                >
                  Remove
                </Button>
              </motion.span>
            ) : null}
          </AnimatePresence>
        </div>
        <p
          className={cn(
            "text-xs",
            error ? "text-destructive" : "text-muted-foreground"
          )}
          aria-live="polite"
        >
          {error ?? `PNG, JPG or WebP, up to ${maxMb} MB.`}
        </p>
      </div>
      <input
        ref={inputRef}
        type="file"
        accept={ACCEPTED.join(",")}
        className="sr-only"
        tabIndex={-1}
        aria-hidden
        onChange={(event) => {
          take(event.target.files?.[0]);
          event.target.value = "";
        }}
      />
    </div>
  );
};

/* ─────────────────────────────────────────────────────────
 * USERNAME
 * A prefix + input that read as one field. Availability is checked
 * after typing stops; the status icon crossfades (150ms, no movement:
 * it changes as you type). Nothing shows under the field until the
 * username changes.
 * ───────────────────────────────────────────────────────── */

export type UsernameStatus =
  | "unchanged"
  | "invalid"
  | "checking"
  | "available"
  | "taken"
  | "error";

export const USERNAME_RULE = /^[a-z0-9_]{3,20}$/;

/** Availability of a username draft: debounced, ignores the saved one. */
export const useUsernameStatus = (
  draft: string,
  saved: string,
  check: (username: string) => Promise<boolean>,
  debounceMs: number
): UsernameStatus => {
  const [checked, setChecked] = useState<{
    available: boolean | null;
    value: string;
  } | null>(null);
  // The latest `check`, so an inline function passed in doesn't restart
  // the check (and loop) on every render.
  const checkRef = useRef(check);
  useEffect(() => {
    checkRef.current = check;
  }, [check]);

  useEffect(() => {
    if (draft === saved || !USERNAME_RULE.test(draft)) {
      return;
    }
    let stale = false;
    const timer = setTimeout(async () => {
      try {
        const available = await checkRef.current(draft);
        if (!stale) {
          setChecked({ available, value: draft });
        }
      } catch {
        if (!stale) {
          setChecked({ available: null, value: draft });
        }
      }
    }, debounceMs);
    return () => {
      stale = true;
      clearTimeout(timer);
    };
  }, [draft, saved, debounceMs]);

  if (draft === saved) {
    return "unchanged";
  }
  if (!USERNAME_RULE.test(draft)) {
    return "invalid";
  }
  if (checked?.value !== draft) {
    return "checking";
  }
  if (checked.available === null) {
    return "error";
  }
  return checked.available ? "available" : "taken";
};

const STATUS_ICON: Partial<Record<UsernameStatus, typeof Alert02Icon>> = {
  available: CheckmarkCircle02Icon,
  checking: Loading03Icon,
  error: Alert02Icon,
  invalid: Alert02Icon,
  taken: Alert02Icon,
};

const StatusIcon = ({ status }: { status: UsernameStatus }) => {
  const icon = STATUS_ICON[status] ?? null;
  const bad = status === "taken" || status === "invalid" || status === "error";
  return (
    <AnimatePresence initial={false} mode="popLayout">
      {icon ? (
        <motion.span
          key={status}
          initial={{ filter: "blur(2px)", opacity: 0 }}
          animate={{ filter: "blur(0px)", opacity: 1 }}
          exit={{ filter: "blur(2px)", opacity: 0 }}
          transition={{ duration: MOTION.status, ease: EASE_OUT }}
          className={cn(
            "flex",
            status === "available" && "text-emerald-600 dark:text-emerald-400",
            bad && "text-destructive",
            status === "checking" && "text-muted-foreground"
          )}
        >
          <HugeiconsIcon
            icon={icon}
            strokeWidth={1.75}
            className={cn(
              "size-4",
              status === "checking" &&
                "animate-[spin_700ms_linear_infinite] motion-reduce:animate-none"
            )}
          />
        </motion.span>
      ) : null}
    </AnimatePresence>
  );
};

const USERNAME_HINT: Record<Exclude<UsernameStatus, "unchanged">, string> = {
  available: "Available.",
  checking: "Checking…",
  error: "Unable to check right now. Try again in a moment.",
  invalid: "3–20 characters: lowercase letters, numbers and _",
  taken: "That username is taken. Try another.",
};

export const UsernameField = ({
  id,
  onChange,
  prefix,
  saved,
  status,
  value,
}: {
  id: string;
  onChange: (value: string) => void;
  prefix: string;
  saved: string;
  status: UsernameStatus;
  value: string;
}) => {
  const hintId = `${id}-hint`;
  const bad = status === "invalid" || status === "taken" || status === "error";

  return (
    <div className="flex flex-col gap-1.5">
      <div
        className={cn(
          RING,
          "dark:bg-input/30 focus-within:border-ring focus-within:ring-ring/50 flex h-9 items-center rounded-md bg-transparent transition-[color,box-shadow] focus-within:ring-[3px]",
          bad &&
            "border-destructive focus-within:border-destructive focus-within:ring-destructive/20"
        )}
      >
        <span className="text-muted-foreground pl-3 text-sm select-none">
          {prefix}
        </span>
        <Input
          id={id}
          value={value}
          onChange={(event) => onChange(event.target.value.toLowerCase())}
          aria-invalid={bad}
          aria-describedby={status === "unchanged" ? undefined : hintId}
          autoComplete="username"
          spellCheck={false}
          // Override: the wrapper draws the border and focus ring.
          className="h-full min-w-0 flex-1 border-0 bg-transparent pl-0.5 shadow-none focus-visible:ring-0 dark:bg-transparent"
        />
        <span className="flex w-9 justify-center">
          <StatusIcon status={status} />
        </span>
      </div>
      {/* Nothing while unchanged: the prefix already says it's a link.
          The hint folds in and out (Reveal) so the rows below glide. */}
      <AnimatePresence initial={false}>
        {status === "unchanged" ? null : (
          <Reveal key="hint">
            <p
              id={hintId}
              aria-live="polite"
              className={cn(
                "text-xs text-pretty",
                bad ? "text-destructive" : "text-muted-foreground"
              )}
            >
              {status === "available"
                ? `Available. Links to ${prefix}${saved} will stop working.`
                : USERNAME_HINT[status]}
            </p>
          </Reveal>
        )}
      </AnimatePresence>
    </div>
  );
};

/* ─────────────────────────────────────────────────────────
 * BIO
 * The counter sits in the box's corner and shows only while you write,
