/* ─────────────────────────────────────────────────────────
 * DATES AND COUNTS (Intl, never hand-built)
 * ───────────────────────────────────────────────────────── */

// "Nov 13" this year, "Oct 24, 2024" before it. UTC, so the server and
// the browser agree.
const SHORT = new Intl.DateTimeFormat("en-US", {
  day: "numeric",
  month: "short",
  timeZone: "UTC",
});
const LONG = new Intl.DateTimeFormat("en-US", {
  day: "numeric",
  month: "short",
  timeZone: "UTC",
  year: "numeric",
});
const formatDay = (iso: string, today: string) => {
  if (iso === today) {
    return "today";
  }
  const format = iso.slice(0, 4) === today.slice(0, 4) ? SHORT : LONG;
  return format.format(new Date(`${iso}T00:00:00Z`));
};

// One whole message per plural category, never a ternary "s".
const PLURAL = new Intl.PluralRules("en-US");
const PASSKEY_COUNT: Partial<
  Record<Intl.LDMLPluralRule, (count: number) => string>
> = {
  one: () => "1 passkey",
  other: (count) => `${count} passkeys`,
};
const passkeyCount = (count: number) =>
  (PASSKEY_COUNT[PLURAL.select(count)] ?? PASSKEY_COUNT.other)?.(count) ?? "";

/* ─────────────────────────────────────────────────────────
 * ROW: logo, name over detail, then the right side (meta + action).
 * ───────────────────────────────────────────────────────── */

const MethodRow = ({
  card = true,
  detail,
  logo,
  name,
  right,
}: {
  // Its own ringed card; off when it sits inside one (the passkeys card).
  card?: boolean;
  detail: React.ReactNode;
  logo: React.ReactNode;
  name: string;
  right: React.ReactNode;
}) => (
  <div
    className={cn(card && CARD, "flex min-h-16 items-center gap-3 px-4 py-3")}
  >
    {logo}
    <div className="flex min-w-0 flex-1 flex-col">
      <p className="text-sm font-medium">{name}</p>
      <div className="text-muted-foreground min-w-0 truncate text-sm">
        {detail}
      </div>
    </div>
    <div className="flex shrink-0 items-center gap-3">{right}</div>
  </div>
);

// The disclosure chevron: 180° in 150ms, ease-out (it answers a click).
const Chevron = ({ open }: { open: boolean }) => (
  <HugeiconsIcon
    icon={ArrowDown01Icon}
    strokeWidth={1.75}
    className={cn(
      "size-4 transition-transform duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none",
      open && "rotate-180",
    )}
  />
);

/* ─────────────────────────────────────────────────────────
 * PASSKEYS
 * ───────────────────────────────────────────────────────── */

// One saved passkey. Remove rolls to a spinner; on success the row folds
// away, so there's no "done" state.
const PasskeyItem = ({
  onRemove,
  passkey,
  today,
}: {
  onRemove: () => Promise<void>;
  passkey: Passkey;
  today: string;
}) => {
  const [state, run] = useButtonState();
  return (
    <div className="flex items-center gap-3 py-1.5 pr-4">
      <div className="min-w-0 flex-1">
        <p className="truncate text-sm">{passkey.name}</p>
        <p className="text-muted-foreground text-xs">
          Added {formatDay(passkey.added, today)}
          {passkey.lastUsed
            ? ` · Last used ${formatDay(passkey.lastUsed, today)}`
            : " · Not used yet"}
        </p>
      </div>
      <StatusButton
        type="button"
        variant="ghost"
        size="sm"
        state={state}
        labels={{ busy: "Removing…", idle: "Remove" }}
        aria-label={
          state === "idle" ? `Remove ${passkey.name} passkey` : undefined
        }
        onClick={() => run(onRemove, false)}
        className="text-muted-foreground hover:text-foreground"
      />
    </div>
  );
};

const PasskeysRow = ({
  initial,
  onAdd,
  onRemove,
  today,
}: {
  initial: Passkey[];
  onAdd: () => Promise<Passkey>;
  onRemove: (id: string) => Promise<void> | void;
  today: string;
}) => {
  const [passkeys, setPasskeys] = useState(initial);
  const [open, setOpen] = useState(false);
  const [state, run] = useButtonState();
  const listId = useId();

  const add = () =>
    run(async () => {
      const passkey = await onAdd();
      setPasskeys((current) => [...current, passkey]);
      setOpen(true);
    });

  const remove = async (id: string) => {
    await onRemove(id);
    setPasskeys((current) => current.filter((item) => item.id !== id));
  };

  return (
    <div className={CARD}>
      <MethodRow
        card={false}
        logo={
          <HugeiconsIcon
            icon={FingerPrintIcon}
            strokeWidth={1.75}
            className="text-foreground size-5 shrink-0"
          />
        }
        name="Passkeys"
        detail={
          passkeys.length === 0 ? (
            "Sign in with your fingerprint or face"
          ) : (
            <button
              type="button"
              aria-expanded={open}
              aria-controls={listId}
              onClick={() => setOpen((value) => !value)}
              className="hover:text-foreground focus-visible:ring-ring/50 inline-flex items-center gap-1 rounded-sm outline-none focus-visible:ring-[3px]"
            >
              {passkeyCount(passkeys.length)}
              <Chevron open={open} />
            </button>
          )
        }
        right={
          <StatusButton
            type="button"
            variant="outline"
            size="sm"
            className={RING_BUTTON}
            state={state}
            labels={{
              busy: "Waiting for device…",
              done: "Added",
              idle: "Add passkey",
            }}
            onClick={add}
          />
        }
      />
      <AnimatePresence initial={false}>
        {open && passkeys.length > 0 ? (
          <Reveal key="passkeys">
            {/* Indented to the names above: 1rem + logo + gap. */}
            <div id={listId} className="flex flex-col pb-2 pl-12">
              <AnimatePresence initial={false}>
                {passkeys.map((passkey) => (
                  <Reveal key={passkey.id}>
                    <PasskeyItem
                      passkey={passkey}
                      today={today}
                      onRemove={() => remove(passkey.id)}
                    />
                  </Reveal>
                ))}
              </AnimatePresence>
            </div>
          </Reveal>
        ) : null}
      </AnimatePresence>
    </div>
  );
};

/* ─────────────────────────────────────────────────────────
 * THE LIST
 * ───────────────────────────────────────────────────────── */

// Most recently used first; one connected just now (no use yet) on top.
const byLastUsed = (a: SignInProvider, b: SignInProvider) =>
  (b.lastUsed ?? "9999").localeCompare(a.lastUsed ?? "9999");

export const SignInMethods = ({ settings }: { settings: SignInSettings }) => {
  const [providers, setProviders] = useState(settings.providers);
  const [moreOpen, setMoreOpen] = useState(false);
  const [connecting, setConnecting] = useState<string | null>(null);
  const moreId = useId();
  const headingId = useId();
  // The day dates are written against ("today", or a year for older ones).
  // Read after mount, never while rendering: server rendering (and Next's
  // cacheComponents prerender) can't depend on the current time. Until
  // then dates show with their year.
  const [today, setToday] = useState("");
  useEffect(() => {
    setToday(new Date().toISOString().slice(0, 10));
  }, []);

  const connected = providers
    .filter((provider) => provider.account)
    .toSorted(byLastUsed);
  const available = providers.filter((provider) => !provider.account);

  const connect = async (id: string) => {
    setConnecting(id);
    try {
      const account = await settings.onConnect(id);
      setProviders((current) =>
        current.map((provider) =>
          provider.id === id
            ? { ...provider, account, lastUsed: null }
            : provider,
        ),
      );
    } finally {
      setConnecting(null);
    }
  };

  const disconnect = async (id: string) => {
    await settings.onDisconnect(id);
    setProviders((current) =>
      current.map((provider) =>
        provider.id === id
          ? { ...provider, account: undefined, lastUsed: undefined }
          : provider,
      ),
    );
    // Show where it went: it's now under More sign-in options.
    setMoreOpen(true);
  };

  return (
    <section aria-labelledby={headingId} className="flex flex-col gap-4 py-6">
      <div className="flex flex-col gap-1">
        <h3 id={headingId} className="text-sm font-medium">
          Sign-in methods
        </h3>
        <p className="text-muted-foreground text-sm">
          Ways to sign in besides your email.
        </p>
      </div>

      {/* A stack of ringed cards, 8px apart. The gap lives inside each
          item (pb-2) so it folds away with a row; 1px of room on every
          side keeps rings unclipped while rows move. */}
      <div className="-mx-px -mt-px -mb-2 flex flex-col">
        <div className="px-px pt-px pb-2">
          <PasskeysRow
            initial={settings.passkeys}
            onAdd={settings.onAddPasskey}
            onRemove={settings.onRemovePasskey}
            today={today}
          />
        </div>

        <AnimatePresence initial={false}>
          {connected.map((provider) => (
            <Reveal key={provider.id} swap className="px-px pt-px pb-2">
              <MethodRow
                logo={<ProviderLogo provider={provider} />}
                name={provider.name}
                detail={provider.account}
                right={
                  <>
                    <span className="text-muted-foreground hidden text-xs sm:inline">
                      {provider.lastUsed
                        ? `Last used ${formatDay(provider.lastUsed, today)}`
                        : "Connected just now"}
                    </span>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon-sm"
                          aria-label={`More actions for ${provider.name}`}
                          className="text-muted-foreground hover:text-foreground"
                        >
                          <HugeiconsIcon
                            icon={MoreHorizontalIcon}
                            strokeWidth={1.75}
                          />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className={FLOAT}>
                        <DropdownMenuItem
                          variant="destructive"
                          onSelect={() => disconnect(provider.id)}
                        >
                          Disconnect {provider.name}
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </>
                }
              />
            </Reveal>
          ))}
        </AnimatePresence>
      </div>

      {available.length > 0 ? (
        <div className="flex flex-col">
          {/* A quiet text toggle, not a row: the cards above are the list. */}
          <button
            type="button"
            aria-expanded={moreOpen}
            aria-controls={moreId}
            onClick={() => setMoreOpen((value) => !value)}
            className="text-muted-foreground hover:text-foreground focus-visible:ring-ring/50 inline-flex h-8 items-center gap-1.5 self-start rounded-sm text-sm outline-none focus-visible:ring-[3px]"
          >
            More sign-in options
            <Chevron open={moreOpen} />
          </button>
          <AnimatePresence initial={false}>
            {moreOpen ? (
              <Reveal
                key="more"
                className="pt-2"
                // ~220px of cards: the tall timing (no slow start).
                enter={0.26}
                exit={0.18}
                tall
              >
                <div id={moreId} className="-mx-px -mt-px -mb-2 flex flex-col">
                  <AnimatePresence initial={false}>
                    {available.map((provider) => (
                      <Reveal
                        key={provider.id}
                        swap
                        className="px-px pt-px pb-2"
                      >
                        <MethodRow
                          logo={<ProviderLogo provider={provider} />}
                          name={provider.name}
                          detail="Not connected"
                          right={
                            <StatusButton
                              type="button"
                              variant="outline"
                              size="sm"
                              className={RING_BUTTON}
                              aria-label={
                                connecting === provider.id
                                  ? undefined
                                  : `Connect ${provider.name}`
                              }
                              disabled={
                                connecting !== null &&
                                connecting !== provider.id
                              }
                              state={
                                connecting === provider.id ? "busy" : "idle"
                              }
                              labels={{ busy: "Connecting…", idle: "Connect" }}
                              onClick={() => connect(provider.id)}
                            />
                          }
                        />
                      </Reveal>
                    ))}
                  </AnimatePresence>
                </div>
              </Reveal>
            ) : null}
          </AnimatePresence>
        </div>
      ) : null}
    </section>
  );
};

"use client";

import {
  AnimatePresence,
  motion,
  useAnimate,
  useReducedMotion,
} from "motion/react";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Kbd } from "@/components/ui/kbd";
import { cn } from "@/lib/utils";

import { EASE_IN_OUT, EASE_OUT, MOTION } from "./motion";
import { StatusButton } from "./status-button";
import type { ButtonState } from "./status-button";
import { FLOAT } from "./surface";

/* ─────────────────────────────────────────────────────────
 * SAVE BAR: only while something changed.
 *
 *    dirty               rises 12px + fades in          220ms ease-out
 *    Save / ⌘S           label rolls up to the spinner   200ms ease-out
 *    saved               rolls to "✓ Saved"; the button keeps one width
 *    +1100ms             sinks out                      180ms ease-out
 *    leave while dirty   shakes x 0,-8,7,-5,3,0         360ms ease-in-out
 *                        "Save or discard…" for 2.4s
 *    Esc                 in a field: leaves the field; else discards
 *    reduced motion      no rise, no shake: fades and the message only
 * ───────────────────────────────────────────────────────── */

export type SaveState = "idle" | "saving" | "saved";

// The bar's save state, as the button's: saving spins, saved shows ✓.
const BUTTON_STATE: Record<SaveState, ButtonState> = {
  idle: "idle",
  saved: "done",
  saving: "busy",
};

// One whole message per plural category (never a ternary "s").
const UNSAVED: Partial<Record<Intl.LDMLPluralRule, (count: number) => string>> =
  {
    one: () => "1 unsaved change",
    other: (count) => `${count} unsaved changes`,
  };
const PLURAL = new Intl.PluralRules("en-US");
const unsavedMessage = (count: number) =>
  (UNSAVED[PLURAL.select(count)] ?? UNSAVED.other)?.(count) ?? "";

// "⌘" on Apple devices, "Ctrl" elsewhere. Read after mount (the bar only
// shows after an edit, so there's no server render to mismatch).
const useModKey = () => {
  const [mod, setMod] = useState("Ctrl");
  useEffect(() => {
    if (/Mac|iPhone|iPad/.test(navigator.userAgent)) {
      setMod("⌘");
    }
  }, []);
  return mod;
};

// Fixed width (the widest of "Save changes ⌘S" and "✓ Saved"): the label
// rolls, the button never resizes. Busy shows the spinner only.
const SaveButton = ({
  disabled,
  onClick,
  shortcut,
  state,
}: {
  disabled?: boolean;
  onClick: () => void;
  shortcut: string;
  state: SaveState;
}) => (
  <StatusButton
    type="button"
    size="sm"
    disabled={disabled}
    state={BUTTON_STATE[state]}
    labels={{ busy: "Saving…", done: "Saved", idle: "Save changes" }}
    trailing={
      // Override: readable on the filled button; hidden on touch screens.
      <Kbd className="bg-primary-foreground/15 text-primary-foreground/80 hidden shadow-none sm:inline-flex">
        {shortcut}
      </Kbd>
    }
    onClick={() => {
      if (state === "idle") {
        onClick();
      }
    }}
  />
);

export const SaveBar = ({
  changedCount,
  nudges,
  onDiscard,
  onSave,
  problem,
  state,
}: {
  changedCount: number;
  nudges: number;
  onDiscard: () => void;
  onSave: () => void;
  problem: string | null;
  state: SaveState;
}) => {
  const reduce = useReducedMotion();
  const [scope, animate] = useAnimate<HTMLDivElement>();
  const mod = useModKey();
  const [warned, setWarned] = useState(false);
  const dirty = changedCount > 0;
  const visible = dirty || state !== "idle";
  const canSave = dirty && state === "idle" && !problem;

  // Someone tried to leave: shake once and say why.
  useEffect(() => {
    if (nudges === 0) {
      return;
    }
    setWarned(true);
    if (!reduce && scope.current) {
      animate(
        scope.current,
        { x: [0, -8, 7, -5, 3, 0] },
        { duration: MOTION.nudge, ease: EASE_IN_OUT }
      );
    }
    const timer = setTimeout(() => setWarned(false), MOTION.nudgeHold);
    return () => clearTimeout(timer);
  }, [nudges, reduce, animate, scope]);

  // The warning is about the pending edits: once saved or discarded, gone.
  useEffect(() => {
    if (!dirty || state !== "idle") {
      setWarned(false);
    }
  }, [dirty, state]);

  // Shortcuts, only while there's something to save.
  useEffect(() => {
    if (!dirty || state !== "idle") {
      return;
    }
    const onKey = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "s") {
        event.preventDefault();
        if (canSave) {
          onSave();
        }
        return;
      }
      if (event.key === "Escape") {
        // First Esc leaves the field you're typing in; the next discards.
        const field = document.activeElement;
        if (
          field instanceof HTMLInputElement ||
          field instanceof HTMLTextAreaElement
        ) {
          field.blur();
          return;
        }
        onDiscard();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [dirty, state, canSave, onSave, onDiscard]);

  // Closing the tab or reloading with unsaved changes asks first.
  useEffect(() => {
    if (!dirty) {
      return;
    }
    const onLeave = (event: BeforeUnloadEvent) => event.preventDefault();
    window.addEventListener("beforeunload", onLeave);
    return () => window.removeEventListener("beforeunload", onLeave);
  }, [dirty]);

  let message = problem ?? unsavedMessage(changedCount);
  if (warned && dirty) {
    message = "Save or discard your changes first";
  }
  if (state === "saved") {
    message = "Changes saved";
  }

  return (
    <div className="pointer-events-none sticky bottom-4 z-10 mt-8 flex justify-center">
      <AnimatePresence>
        {visible ? (
          <motion.div
            initial={
              reduce ? { opacity: 0 } : { opacity: 0, y: MOTION.bar.rise }
            }
            animate={{
              opacity: 1,
              transition: { duration: MOTION.bar.enter, ease: EASE_OUT },
              y: 0,
            }}
            exit={{
              opacity: 0,
              transition: { duration: MOTION.bar.exit, ease: EASE_OUT },
              y: reduce ? 0 : MOTION.bar.rise,
            }}
            className="pointer-events-auto w-full sm:w-auto"
          >
            {/* The shake moves this inner box; the outer one rises in. */}
            <div
              ref={scope}
              role="region"
              aria-label="Unsaved changes"
              className={cn(
                FLOAT,
                "bg-popover text-popover-foreground flex items-center gap-3 rounded-xl p-2 pl-4 sm:w-[33rem]"
              )}
            >
              <p
                className={cn(
                  "flex-1 text-sm",
                  warned && dirty ? "text-foreground" : "text-muted-foreground"
                )}
                aria-live="polite"
              >
                {message}
              </p>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                disabled={state !== "idle"}
                onClick={onDiscard}
              >
                Discard
                <Kbd className="hidden sm:inline-flex">Esc</Kbd>
              </Button>
              <SaveButton
                state={state}
                shortcut={`${mod}S`}
                disabled={Boolean(problem)}
                onClick={onSave}
              />
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
};

"use client";

import {
  AnimatePresence,
  motion,
  PresenceContext,
  useAnimate,
  useReducedMotion,
} from "motion/react";
import type * as React from "react";
import {
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

/* ─────────────────────────────────────────────────────────
 * MOTION for the profile settings block.
 *
 *   entering / exiting   ease-out    (0.23, 1, 0.32, 1)
 *   moving on screen     ease-in-out (0.645, 0.045, 0.355, 1)
 *   everything ≤ 260ms, exits ~30% faster than entrances
 *   typing, focus, keyboard: never animated
 *   reduced motion: opacity only, no travel, no height, no scale
 * ───────────────────────────────────────────────────────── */

export const EASE_OUT = [0.23, 1, 0.32, 1] as const;
export const EASE_IN_OUT = [0.645, 0.045, 0.355, 1] as const;
// Quadratic ease-out: speed falls in a straight line from 2× average to 0.
// Moves from the first frame (12% at 16ms over 260ms), never jumps more
// than 12% a frame, and has no long creeping tail: one continuous motion.
// For tall reveals, where ease-in-out's slow start reads as a second step.
export const EASE_OUT_QUAD = [0.5, 1, 0.89, 1] as const;

export const MOTION = {
  // The save bar rising in once something changes, and sinking out.
  bar: { enter: 0.22, exit: 0.18, rise: 12 },
  // Leaving with unsaved changes: the bar shakes once, and its message
  // says why for this long (ms).
  nudge: 0.36,
  nudgeHold: 2400,
  // Something opening below a field (email actions, notes, lists).
  reveal: { enter: 0.21, exit: 0.15 },
  // How long "Saved" stays before the bar settles (ms).
  savedHold: 1100,
  // Status icons (spinner → check), dots, small swaps.
  status: 0.15,
  // A new photo crossfading in.
  swap: 0.2,
  // One thing replaced by another in place: the old one fades out
  // quickly, the new one in just after, so they barely overlap.
  swapSpace: { in: 0.16, inDelay: 0.04, out: 0.12 },
};

/** Resolves after `ms`: the demo's stand-in for a network call. */
export const wait = (ms: number) =>
  // oxlint-disable-next-line promise/avoid-new
  new Promise<void>((resolve) => {
    setTimeout(resolve, ms);
  });

/* ─────────────────────────────────────────────────────────
 * REVEAL: something appearing below what's already there, so the rows
 * under it slide instead of jumping.
 *
 *   height 0 ↔ auto   210ms ease-in-out (the rows below are on screen
 *                     and moving; a strong ease-out did 60% of the
 *                     travel in the first frame, which read as a jump)
 *   opacity 0 ↔ 1     210ms ease-out (the content is entering)
 *   exit              150ms, or 210ms when it swaps with another Reveal
 *   tall              for anything ~150px or taller: pass `tall` with
 *                     `enter` / `exit` (e.g. 0.26 / 0.18). Height and fade
 *                     both on EASE_OUT_QUAD, the fade with no delay (60%
 *                     of the open, 50% of the close): one motion, no slow
 *                     start, gone before the box gets small
 *   reduced motion    opacity only
 *
 * Animates to "auto", never a measured number, so a Reveal inside a
 * Reveal moves frame for frame. Clips only while moving, so focus rings
 * show once it's open; a Reveal already there on first paint (inside
 * AnimatePresence initial={false}) never animates, so it starts unclipped. Spacing goes inside (`className`), so nothing is
 * left over when it unmounts.
 * ───────────────────────────────────────────────────────── */

export const Reveal = ({
  children,
  className,
  enter = MOTION.reveal.enter,
  exit,
  swap = false,
  tall = false,
}: {
  children: React.ReactNode;
  className?: string;
  /** Open duration, seconds. */
  enter?: number;
  /** Close duration, seconds. */
  exit?: number;
  // Trades places with another Reveal (one leaves as the other arrives):
  // both run at the enter duration, so their heights cross smoothly and
  // the rows below move one way only.
  swap?: boolean;
  /** Tall content: EASE_OUT_QUAD for height and fade, quick fade. */
  tall?: boolean;
}) => {
  const reduce = useReducedMotion();
  const exitDuration = exit ?? (swap ? enter : MOTION.reveal.exit);
  // Clip only while it moves. Rows already there on first paint never
  // animate, so they must start unclipped (or stay clipped for good).
  const presence = useContext(PresenceContext);
  const animatesIn = presence?.initial !== false;
  const [moving, setMoving] = useState(!reduce && animatesIn);
  const timing = (duration: number, opening: boolean) => {
    const fade = tall ? duration * (opening ? 0.6 : 0.5) : duration;
    return {
      height: { duration, ease: tall ? EASE_OUT_QUAD : EASE_IN_OUT },
      opacity: { duration: fade, ease: tall ? EASE_OUT_QUAD : EASE_OUT },
    };
  };
  return (
    <motion.div
      initial={reduce ? { opacity: 0 } : { height: 0, opacity: 0 }}
      animate={{
        height: "auto",
        opacity: 1,
        transition: timing(enter, true),
      }}
      exit={
        reduce
          ? { opacity: 0, transition: { duration: exitDuration } }
          : { height: 0, opacity: 0, transition: timing(exitDuration, false) }
      }
      onAnimationStart={() => setMoving(!reduce)}
      onAnimationComplete={() => setMoving(false)}
      style={{ overflow: moving ? "hidden" : "visible" }}
    >
      <div className={className}>{children}</div>
    </motion.div>
  );
};

/* ─────────────────────────────────────────────────────────
 * SWAP SPACE: one thing replaced by another in the same place (the
 * secondary email ↔ "Add secondary email").
 *
 *   contents   crossfade in place, top-aligned: the old one leaves the
 *              layout at once (popLayout), so the new one never travels
 *              out 120ms ease-out · in 160ms ease-out, 40ms later
 *   space      height old → new, 210ms ease-in-out, clipped meanwhile,
 *              then back to auto so later changes inside follow on
 *              their own
 *   reduced motion: the crossfade only, the height snaps
 * ───────────────────────────────────────────────────────── */

export const SwapSpace = ({
  children,
  swapKey,
}: {
  children: React.ReactNode;
  swapKey: string;
}) => {
  const reduce = useReducedMotion();
  const [scope, animate] = useAnimate<HTMLDivElement>();
  // The last height at rest, read before a swap changes it.
  const settled = useRef<number | null>(null);
  const moving = useRef(false);
  const lastKey = useRef(swapKey);

  useEffect(() => {
    const el = scope.current;
    if (!el) {
      return;
    }
    const observer = new ResizeObserver(() => {
      if (!moving.current) {
        settled.current = el.offsetHeight;
      }
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [scope]);

  useLayoutEffect(() => {
    const el = scope.current;
    const from = settled.current;
    if (lastKey.current === swapKey) {
      return;
    }
    lastKey.current = swapKey;
    if (!el || from === null || reduce) {
      return;
    }
    // The leaving content is already out of the flow: this is the new size.
    const to = el.offsetHeight;
    if (to === from) {
      return;
    }
    moving.current = true;
    // Pin the old height before paint, so no frame shows the new one early.
    el.style.height = `${from}px`;
    el.style.overflow = "hidden";
    const run = async () => {
      await animate(
        el,
        { height: [`${from}px`, `${to}px`] },
        { duration: MOTION.reveal.enter, ease: EASE_IN_OUT }
      );
      el.style.height = "";
      el.style.overflow = "";
      moving.current = false;
      settled.current = el.offsetHeight;
    };
    run();
  }, [swapKey, reduce, animate, scope]);

  return (
    <div ref={scope} className="relative">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.div
          key={swapKey}
          initial={{ opacity: 0 }}
          animate={{
            opacity: 1,
            transition: {
              delay: MOTION.swapSpace.inDelay,
              duration: MOTION.swapSpace.in,
              ease: EASE_OUT,
            },
          }}
          exit={{
            opacity: 0,
            transition: { duration: MOTION.swapSpace.out, ease: EASE_OUT },
          }}
        >
          {children}
        </motion.div>
      </AnimatePresence>
    </div>
  );
};

"use client";

import {
  CheckmarkCircle02Icon,
  Loading03Icon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import type { IconSvgElement } from "@hugeicons/react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type * as React from "react";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { EASE_OUT } from "./motion";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: an async button whose label rolls to its new state.
 *
 *   [ Add passkey ]  click
 *        ↑ label leaves upward (y 0 → -100%, fades)
 *        ↑ the spinner rises in from below (y 100% → 0)
 *   [      ◌      ]  spinner only, centred (busy words: screen readers only)
 *   [   ✓ Added   ]  same roll; back to idle after 1.5s
 *
 * FIXED WIDTH: the button never changes size. Every state's label is
 * stacked invisibly in one grid cell, so the button is as wide as its
 * longest label from the first paint; the visible label is centred on top.
 *
 * MOTION
 *   label roll    200ms ease-out, out and in together (popLayout, so the
 *                 two labels pass like a conveyor, never stacked)
 *   spinner       600ms a turn (a fast spinner reads as a fast app)
 *   press         0.96 scale, from the shadcn button itself
 *   reduced       labels cross-fade in place; the spinner holds still
 *
 * While busy the button is aria-disabled, not disabled: it keeps full
 * colour (shadcn dims disabled buttons, which would fade the loader) and
 * keeps keyboard focus; clicks are ignored. aria-busy tells screen readers.
 *
 * `trailing` (e.g. a ⌘S key hint) shows after the idle words only, and
 * is part of the idle sizer, so the width still never changes.
 * ───────────────────────────────────────────────────────── */

export type ButtonState = "idle" | "busy" | "done";

const ROLL = { duration: 0.2, ease: EASE_OUT };

const StateIcon = ({
  icon,
  state,
}: {
  icon?: IconSvgElement;
  state: ButtonState;
}) => {
  if (state === "busy") {
    return (
      <HugeiconsIcon
        icon={Loading03Icon}
        strokeWidth={2}
        className="size-4 animate-[spin_600ms_linear_infinite] motion-reduce:animate-none"
      />
    );
  }
  if (state === "done") {
    return (
      <HugeiconsIcon
        icon={CheckmarkCircle02Icon}
        strokeWidth={2}
        className="size-4 text-emerald-600 dark:text-emerald-400"
      />
    );
  }
  return icon ? (
    <HugeiconsIcon icon={icon} strokeWidth={1.75} className="size-4" />
  ) : null;
};

interface Labels {
  idle: string;
  busy?: string;
  done?: string;
}

const STATES: ButtonState[] = ["idle", "busy", "done"];

// The label for a state: the spinner alone while busy (its words go to
// screen readers), otherwise the state's icon and words.
const LabelContent = ({
  icon,
  labels,
  state,
  trailing,
}: {
  icon?: IconSvgElement;
  labels: Labels;
  state: ButtonState;
  trailing?: React.ReactNode;
}) => (
  <>
    <StateIcon icon={icon} state={state} />
    {state === "busy" ? (
      <span className="sr-only">{labels.busy ?? labels.idle}</span>
    ) : (
      (labels[state] ?? labels.idle)
    )}
    {state === "idle" ? trailing : null}
  </>
);

// The rolling label. Keyed by state + text, so any change of words rolls
// (Continue → Verify in a dialog), not only a change of state.
export const RollingLabel = ({
  icon,
  labels,
  reserve = [],
  state,
  trailing,
}: {
  icon?: IconSvgElement;
  labels: Labels;
  /** Other words this button can show (e.g. "Set up" ↔ "Turn off"): room is kept for them too. */
  reserve?: string[];
  state: ButtonState;
  /** Shown after the idle words only (e.g. a key hint). */
  trailing?: React.ReactNode;
}) => {
  const reduce = useReducedMotion();
  const cell = "col-start-1 row-start-1 flex items-center justify-center";
  return (
    <span className="inline-grid overflow-hidden">
      {/* Sizers: every state, invisible, in the same cell. */}
      {/* Only the states this button uses: a "done" it never shows
          would reserve room for a ✓ it never draws. */}
      {STATES.filter((each) => each === "idle" || labels[each]).map((each) => (
        <span
          key={each}
          aria-hidden
          className={cn(cell, "invisible gap-1.5 whitespace-nowrap")}
        >
          <LabelContent
            icon={icon}
            labels={labels}
            state={each}
            trailing={trailing}
          />
        </span>
      ))}
      {reserve.map((words) => (
        <span
          key={`reserve:${words}`}
          aria-hidden
          className={cn(cell, "invisible gap-1.5 whitespace-nowrap")}
        >
          {words}
        </span>
      ))}
      <span className={cn(cell, "relative")}>
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            key={`${state}:${labels[state] ?? labels.idle}`}
            className="inline-flex items-center gap-1.5 whitespace-nowrap"
            initial={{ opacity: 0, y: reduce ? 0 : "100%" }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: reduce ? 0 : "-100%" }}
            transition={ROLL}
          >
            <LabelContent
              icon={icon}
              labels={labels}
              state={state}
              trailing={trailing}
            />
          </motion.span>
        </AnimatePresence>
      </span>
    </span>
  );
};

type StatusButtonProps = Omit<
  React.ComponentProps<typeof Button>,
  "children"
> & {
  /** Idle, busy (spinner) or done (check). */
  state: ButtonState;
  /** The words for each state; busy and done fall back to idle. */
  labels: Labels;
  /** Icon shown while idle. */
  icon?: IconSvgElement;
  /** Shown after the idle words only (e.g. a key hint). */
  trailing?: React.ReactNode;
};

export const StatusButton = ({
  className,
  icon,
  labels,
  onClick,
  state,
  trailing,
  ...props
}: StatusButtonProps) => {
  const busy = state === "busy";
  return (
    <Button
      {...props}
      aria-busy={busy || undefined}
      aria-disabled={busy || props["aria-disabled"] || undefined}
      onClick={(event) => {
        if (!busy) {
          onClick?.(event);
        }
      }}
      className={cn(busy && "cursor-progress", className)}
    >
      <RollingLabel
        icon={icon}
        state={state}
        labels={labels}
        trailing={trailing}
      />
    </Button>
  );
};

/**
 * Runs an async action as idle → busy → done → idle. Returns the state
 * and `run`, which resolves true on success; on failure it goes straight
 * back to idle and resolves false (show your own error message).
 */
export const useButtonState = (doneFor = 1500) => {
  const [state, setState] = useState<ButtonState>("idle");
  useEffect(() => {
    if (state !== "done") {
      return;
    }
    const timer = setTimeout(() => setState("idle"), doneFor);
    return () => clearTimeout(timer);
  }, [state, doneFor]);

  const run = async (action: () => Promise<unknown>, showDone = true) => {
    setState("busy");
    try {
      await action();
    } catch {
      setState("idle");
      return false;
    }
    setState(showDone ? "done" : "idle");
    return true;
  };

  return [state, run] as const;
};

/* ─────────────────────────────────────────────────────────
 * SURFACES: shadows for elevation, not borders.
 *
 *   lift    surfaces: soft depth only, no ring (light); card colour (dark)
 *   ring    form fields only: a faint 1px ring so a field can be found
 *   float   the save bar: the same ring with a deeper lift, it hovers
 *   photo   an inset ring and a soft inner shadow, so the photo's edge
 *           reads crisply on any page colour (pure black / white, never
 *           a tint, which would fringe the image)
 *
 * Every ring keeps a transparent 1px border underneath: forced-colors
 * mode drops box-shadow and paints that border instead, and the box stays
 * the size the border gave it. Error and focus borders still colour it.
 * No dividers anywhere: rows are grouped by space, and a list is a stack
 * of ringed cards (CARD), 8px apart, so every edge is a shadow, never a
 * rule.
 * ───────────────────────────────────────────────────────── */

// Surfaces (cards, panels, frames): depth only, NO 1px ring. A ring reads
// as a border, and the user wants no lines. Light: three soft layers
// (contact, lift, ambient). Dark: depth shadows vanish on dark, so the
// card colour (lighter than the page) lifts it instead: no shadow at all.
export const LIFT =
  "border border-transparent shadow-[0_1px_2px_0_oklch(0_0_0/0.05),0_2px_8px_-2px_oklch(0_0_0/0.08),0_8px_24px_-8px_oklch(0_0_0/0.08)] dark:shadow-none";

// Form fields (inputs, textareas, checkboxes, radios, code boxes) keep a
// faint 1px ring: a field needs a visible boundary to be found.
export const RING =
  "border border-transparent shadow-[0_0_0_1px_oklch(0_0_0/0.08),0_1px_2px_-1px_oklch(0_0_0/0.06),0_2px_4px_0_oklch(0_0_0/0.04)] dark:shadow-[0_0_0_1px_oklch(1_0_0/0.1)]";

export const FLOAT =
  "border border-transparent shadow-[0_2px_4px_-1px_oklch(0_0_0/0.06),0_8px_16px_-4px_oklch(0_0_0/0.1),0_16px_32px_-8px_oklch(0_0_0/0.14)] dark:shadow-[0_12px_24px_-4px_oklch(0_0_0/0.5)]";

export const PHOTO_INSET =
  "pointer-events-none absolute inset-0 rounded-full shadow-[inset_0_0_0_1px_oklch(0_0_0/0.1),inset_0_1px_3px_oklch(0_0_0/0.12)] dark:shadow-[inset_0_0_0_1px_oklch(1_0_0/0.1),inset_0_1px_3px_oklch(0_0_0/0.4)]";

// A list row: its own lifted card on the card colour.
export const CARD = `${LIFT} bg-card rounded-lg`;

// Outline buttons: a small contact shadow, no ring (light); in dark the
// outline variant's own fill (bg-input/30) shapes it. shadcn's outline
// border is cleared in both themes.
export const RING_BUTTON =
  "border border-transparent shadow-[0_1px_2px_0_oklch(0_0_0/0.1),0_1px_3px_0_oklch(0_0_0/0.06)] hover:shadow-[0_1px_2px_0_oklch(0_0_0/0.12),0_2px_6px_-1px_oklch(0_0_0/0.1)] dark:border-transparent dark:shadow-none dark:hover:shadow-none";
